import{_ as t,o as n,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Tabel Ringkas Kronik","description":"","frontmatter":{},"headers":[],"relativePath":"id/93-编年史简表.md","filePath":"id/93-编年史简表.md"}'),r={name:"id/93-编年史简表.md"};function d(s,a,u,m,k,h){return n(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="tabel-ringkas-kronik" tabindex="-1">Tabel Ringkas Kronik <a class="header-anchor" href="#tabel-ringkas-kronik" aria-label="Permalink to &quot;Tabel Ringkas Kronik&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>93</td></tr><tr><td>Modul</td><td>Lampiran dan Bahan Rujukan</td></tr><tr><td>Kata Kunci Inti</td><td>kronik, pembagian era, peristiwa penting, simpul sejarah, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-deskripsi-kronik" tabindex="-1">1. Deskripsi Kronik <a class="header-anchor" href="#_1-deskripsi-kronik" aria-label="Permalink to &quot;1. Deskripsi Kronik&quot;">​</a></h2><p>Tabel ringkas ini berbasis waktu standar Hengyuanzhou, mencatat secara kronologis peristiwa sejarah penting dan simpul kunci dalam perjalanan perkembangan Peradaban Simbiosis Jangkar. Rentang waktu membentang dari periode kuno era pra-jangkar hingga prospek masa depan era simbiosis antarbintang. Setiap era mencantumkan waktu mulai dan berakhir, ciri-ciri era, dan peristiwa penting. Tabel ringkas ini adalah indeks sejarah yang sangat terkondensasi; untuk sejarah rinci setiap era, silakan lihat tulisan khusus dokumen 70-79.</p><h2 id="_2-tinjauan-umum-pembagian-era" tabindex="-1">2. Tinjauan Umum Pembagian Era <a class="header-anchor" href="#_2-tinjauan-umum-pembagian-era" aria-label="Permalink to &quot;2. Tinjauan Umum Pembagian Era&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor Era</th><th>Nama Era</th><th>Waktu Mulai dan Berakhir (tahun standar Hengyuanzhou)</th><th>Durasi</th><th>Ciri Inti</th></tr></thead><tbody><tr><td>Era Pertama</td><td>Era Pra-Jangkar</td><td>Sekitar -10 miliar hingga -10.000 tahun</td><td>Sekitar 10 miliar tahun</td><td>Sistem kultivasi gaya penjarahan dominan, siklus naik-turunnya peradaban</td></tr><tr><td>Era Kedua</td><td>Era Kebangkitan Jangkar</td><td>-10.000 hingga -1.000 tahun</td><td>Sekitar 9.000 tahun</td><td>Mekanisme jangkar ditemukan dan diterapkan awal</td></tr><tr><td>Era Ketiga</td><td>Periode Pembentukan Sistem Simbiosis</td><td>-1.000 hingga -100 tahun</td><td>Sekitar 900 tahun</td><td>Kerangka institusional Peradaban Simbiosis Jangkar secara bertahap terbentuk</td></tr><tr><td>Era Keempat</td><td>Periode Pembukaan Sistem Tiga Ratus Set</td><td>-100 hingga -50 tahun</td><td>Sekitar 50 tahun</td><td>Sistem kultivasi asal tiga ratus set sepenuhnya dibuka</td></tr><tr><td>Era Kelima</td><td>Periode Strategi Aktivasi 20%</td><td>-50 tahun hingga tahun nol</td><td>Sekitar 50 tahun</td><td>20% makhluk berkesadaran diaktifkan menjadi makhluk tertinggi bidang</td></tr><tr><td>Era Keenam</td><td>Era Peningkatan Dimensi Pertama</td><td>Tahun nol hingga 100 tahun</td><td>100 tahun</td><td>Peradaban simbiosis untuk pertama kalinya mencapai peningkatan dimensi bertahap</td></tr><tr><td>Era Ketujuh</td><td>Era Republik Semua Ras</td><td>100 hingga 500 tahun</td><td>400 tahun</td><td>Republik semua ras secara resmi terbentuk, peleburan antar-ras diperdalam</td></tr><tr><td>Era Kedelapan</td><td>Era Eksplorasi Antar-Bidang</td><td>500 hingga 2.000 tahun</td><td>1.500 tahun</td><td>Eksplorasi dan kegiatan arkeologi skala besar antar-bidang dimulai</td></tr><tr><td>Era Kesembilan</td><td>Era Simbiosis Antarbintang</td><td>2.000 tahun hingga masa depan</td><td>Berlangsung</td><td>Jaringan simbiosis kosmik terbentuk, peningkatan dimensi keseluruhan maju</td></tr></tbody></table><p>Catatan: &quot;Tahun nol&quot; merujuk pada tahun di mana Peradaban Simbiosis Jangkar secara resmi mengumumkan pembentukannya, digunakan sebagai titik pembagi kronologi sejarah.</p><h2 id="_3-era-pra-jangkar-sekitar-10-miliar-hingga-10-000-tahun" tabindex="-1">3. Era Pra-Jangkar (Sekitar -10 miliar hingga -10.000 tahun) <a class="header-anchor" href="#_3-era-pra-jangkar-sekitar-10-miliar-hingga-10-000-tahun" aria-label="Permalink to &quot;3. Era Pra-Jangkar (Sekitar -10 miliar hingga -10.000 tahun)&quot;">​</a></h2><p>Era pra-jangkar adalah era terpanjang dalam sejarah Hengyuanzhou, berlangsung sekitar sepuluh miliar tahun. Ciri inti era ini adalah sistem kultivasi gaya penjarahan mendominasi alam semesta, dan peradaban berulang kali berputar dalam siklus &quot;kebangkitan—puncak—penjarahan—keruntuhan&quot;.</p><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>Sekitar -10 miliar tahun</td><td>Jaringan hukum Hengyuanzhou stabil, bidang materi pertama terbentuk, alam semesta memasuki keadaan layak huni</td></tr><tr><td>Sekitar -8 miliar tahun</td><td>Makhluk cerdas pertama lahir di berbagai bidang materi, sistem kultivasi primitif mulai bertunas</td></tr><tr><td>Sekitar -5 miliar tahun</td><td>Sistem kultivasi gaya penjarahan secara bertahap menjadi arus utama, yang kuat berevolusi cepat dengan memangsa yang lemah</td></tr><tr><td>Sekitar -3 miliar tahun</td><td>Perang penjarahan kosmik pertama meletus, peradaban di berbagai domain bintang menderita pukulan menghancurkan</td></tr><tr><td>Sekitar -1 miliar tahun</td><td>Kekurangan sistem gaya penjarahan mulai muncul, entropi keseluruhan alam semesta meningkat cepat, sumber daya kultivasi semakin menipis</td></tr><tr><td>Sekitar -500 juta tahun</td><td>Pemikir pertama yang merenungkan sistem gaya penjarahan muncul, tunas pemikiran simbiosis mulai terbentuk</td></tr><tr><td>Sekitar -100 juta tahun</td><td>Peradaban eksperimental simbiosis skala kecil muncul di berbagai domain bintang, tetapi semuanya dihancurkan oleh peradaban gaya penjarahan</td></tr><tr><td>Sekitar -1 juta tahun</td><td>Alam semesta secara keseluruhan memasuki &quot;periode kemunduran besar&quot;, jumlah peradaban dan tingkat kultivasi keduanya turun ke titik terendah sejarah</td></tr><tr><td>Sekitar -10.000 tahun</td><td>Seorang kultivator dari bidang pertama secara tidak sengaja merasakan simpul stabil dalam jaringan hukum selama kultivasi jangka panjang, mekanisme jangkar ditemukan untuk pertama kalinya</td></tr></tbody></table><h2 id="_4-era-kebangkitan-jangkar-10-000-hingga-1-000-tahun" tabindex="-1">4. Era Kebangkitan Jangkar (-10.000 hingga -1.000 tahun) <a class="header-anchor" href="#_4-era-kebangkitan-jangkar-10-000-hingga-1-000-tahun" aria-label="Permalink to &quot;4. Era Kebangkitan Jangkar (-10.000 hingga -1.000 tahun)&quot;">​</a></h2><p>Era kebangkitan jangkar adalah periode transisi dari penemuan ke penerapan awal mekanisme jangkar. Ciri inti era ini adalah pematangan bertahap teknologi jangkar dan penyebaran pemikiran simbiosis.</p><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>-10.000 tahun</td><td>Mekanisme jangkar ditemukan untuk pertama kalinya, penemu menamainya &quot;jangkar&quot;, dan memulai penelitian sistematis</td></tr><tr><td>-9.000 tahun</td><td>Jangkar buatan pertama berhasil dibangun, membuktikan bahwa jangkar dapat dibangun dan dipelihara secara artifisial</td></tr><tr><td>-8.000 tahun</td><td>Teknologi jangkar mulai menyebar dalam skala kecil, kultivator jangkar pertama muncul</td></tr><tr><td>-7.000 tahun</td><td>Ditemukan bahwa jangkar dapat berfungsi sebagai dasar koneksi antar-bidang, perjalanan antar-bidang berbantuan jangkar pertama yang tercatat berhasil</td></tr><tr><td>-6.000 tahun</td><td>Pemikiran simbiosis dan teknologi jangkar mulai bergabung, dokumen teoretis &quot;simbiosis jangkar&quot; pertama diterbitkan</td></tr><tr><td>-5.000 tahun</td><td>Kota-negara tipe simbiosis pertama berbasis jangkar terbentuk, membuktikan kelayakan sistem simbiosis</td></tr><tr><td>-4.000 tahun</td><td>Peradaban gaya penjarahan melancarkan serangan terhadap kota-negara tipe simbiosis, kota-negara simbiosis berhasil bertahan melalui teknologi jangkar</td></tr><tr><td>-3.000 tahun</td><td>Pemikiran simbiosis menyebar di berbagai domain bintang, semakin banyak peradaban mulai mencoba transformasi simbiosis</td></tr><tr><td>-2.000 tahun</td><td>&quot;Konferensi Simbiosis Semua Ras&quot; pertama diadakan, perwakilan dari puluhan ras bersama-sama membahas masa depan peradaban simbiosis</td></tr><tr><td>-1.000 tahun</td><td>Teknologi jangkar dan pemikiran simbiosis telah memenuhi syarat untuk membentuk peradaban terpadu, periode pembentukan sistem simbiosis dimulai</td></tr></tbody></table><h2 id="_5-periode-pembentukan-sistem-simbiosis-1-000-hingga-100-tahun" tabindex="-1">5. Periode Pembentukan Sistem Simbiosis (-1.000 hingga -100 tahun) <a class="header-anchor" href="#_5-periode-pembentukan-sistem-simbiosis-1-000-hingga-100-tahun" aria-label="Permalink to &quot;5. Periode Pembentukan Sistem Simbiosis (-1.000 hingga -100 tahun)&quot;">​</a></h2><p>Periode pembentukan sistem simbiosis adalah periode kritis di mana kerangka institusional Peradaban Simbiosis Jangkar terbentuk dari ketiadaan.</p><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>-1.000 tahun</td><td>Komisi penyusunan Konstitusi Simbiosis terbentuk, mulai menyusun hukum dasar</td></tr><tr><td>-950 tahun</td><td>Rancangan &quot;Konstitusi Simbiosis&quot; selesai, mulai meminta pendapat secara luas dari semua ras</td></tr><tr><td>-900 tahun</td><td>&quot;Konstitusi Simbiosis&quot; disahkan melalui referendum nasional, resmi berlaku, Peradaban Simbiosis Jangkar diumumkan terbentuk</td></tr><tr><td>-850 tahun</td><td>Dewan Jangkar, Komite Eksekutif Simbiosis, Pengadilan Simbiosis tiga lembaga utama secara resmi terbentuk dan beroperasi</td></tr><tr><td>-800 tahun</td><td>Mekanisme kontrak produksi bersama mulai diterapkan di seluruh negeri</td></tr><tr><td>-700 tahun</td><td>&quot;Hukum Ketenagakerjaan Simbiosis&quot;, &quot;Hukum Perlindungan Konsumen&quot; dan hukum dasar lainnya diterbitkan secara berturut-turut</td></tr><tr><td>-600 tahun</td><td>Lima hukum pendukung pendidikan, kesehatan, perumahan, lingkungan, dan antimonopoli semuanya diterbitkan dan diterapkan</td></tr><tr><td>-500 tahun</td><td>Pekerjaan penggalian dan penyusunan sistem kultivasi asal tiga ratus set secara resmi dimulai</td></tr><tr><td>-400 tahun</td><td>Lima puluh set pertama sistem kultivasi asal selesai disusun dan diverifikasi</td></tr><tr><td>-300 tahun</td><td>Penerapan teknologi buah penggandaan mencapai terobosan, teknologi amplifikasi deduksi seratus kali matang</td></tr><tr><td>-200 tahun</td><td>Semua tiga ratus set sistem selesai disusun, memasuki tahap verifikasi keamanan akhir</td></tr><tr><td>-100 tahun</td><td>Syarat pembukaan penuh sistem kultivasi asal tiga ratus set matang, memasuki periode pembukaan</td></tr></tbody></table><h2 id="_6-periode-pembukaan-sistem-tiga-ratus-set-100-hingga-50-tahun" tabindex="-1">6. Periode Pembukaan Sistem Tiga Ratus Set (-100 hingga -50 tahun) <a class="header-anchor" href="#_6-periode-pembukaan-sistem-tiga-ratus-set-100-hingga-50-tahun" aria-label="Permalink to &quot;6. Periode Pembukaan Sistem Tiga Ratus Set (-100 hingga -50 tahun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>-100 tahun</td><td>Sistem kultivasi asal tiga ratus set secara resmi dibuka gratis untuk semua makhluk berkesadaran di alam semesta</td></tr><tr><td>-90 tahun</td><td>Jumlah kultivator meningkat seratus kali dalam sepuluh tahun, &quot;semua orang punya jalan&quot; awalnya terwujud</td></tr><tr><td>-80 tahun</td><td>Tiga fondasi asal (iterasi deduksi, siklus kehidupan, penjadwalan hukum ruang) menjadi sistem yang paling populer</td></tr><tr><td>-70 tahun</td><td>Kultivator pertama yang mencapai tingkat tinggi melalui sistem baru muncul, membuktikan efektivitas sistem</td></tr><tr><td>-60 tahun</td><td>Jaringan mentor sepenuhnya terbentuk, kultivator tingkat tinggi mulai memenuhi kewajiban hukum membimbing kultivator junior</td></tr><tr><td>-50 tahun</td><td>Tingkat kultivasi seluruh rakyat meningkat signifikan, syarat strategi aktivasi 20% matang</td></tr></tbody></table><h2 id="_7-periode-strategi-aktivasi-20-50-tahun-hingga-tahun-nol" tabindex="-1">7. Periode Strategi Aktivasi 20% (-50 tahun hingga tahun nol) <a class="header-anchor" href="#_7-periode-strategi-aktivasi-20-50-tahun-hingga-tahun-nol" aria-label="Permalink to &quot;7. Periode Strategi Aktivasi 20% (-50 tahun hingga tahun nol)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>-50 tahun</td><td>Strategi aktivasi 20% secara resmi dimulai, tujuannya adalah mengaktifkan 20% makhluk berkesadaran menjadi makhluk tertinggi bidang dalam 50 tahun</td></tr><tr><td>-40 tahun</td><td>Makhluk tertinggi bidang pertama lahir, tingkat aktivasi mencapai 5%</td></tr><tr><td>-30 tahun</td><td>Tingkat aktivasi mencapai 10%, makhluk tertinggi bidang mulai memainkan peran inti dalam pemeliharaan jangkar</td></tr><tr><td>-20 tahun</td><td>Tingkat aktivasi mencapai 15%, tingkat kultivasi keseluruhan alam semesta mencapai lompatan kualitatif</td></tr><tr><td>-10 tahun</td><td>Tingkat aktivasi mencapai 18%, mendekati target strategis</td></tr><tr><td>Tahun nol</td><td>Tingkat aktivasi mencapai 20,3%, strategi aktivasi 20% selesai dengan sukses, Peradaban Simbiosis Jangkar memasuki era baru</td></tr></tbody></table><h2 id="_8-era-peningkatan-dimensi-pertama-tahun-nol-hingga-100-tahun" tabindex="-1">8. Era Peningkatan Dimensi Pertama (Tahun nol hingga 100 tahun) <a class="header-anchor" href="#_8-era-peningkatan-dimensi-pertama-tahun-nol-hingga-100-tahun" aria-label="Permalink to &quot;8. Era Peningkatan Dimensi Pertama (Tahun nol hingga 100 tahun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>Tahun nol</td><td>Peradaban simbiosis secara resmi mengumumkan memasuki era peningkatan dimensi, tahap pertama dari jalur peningkatan dimensi empat tahap (fondasi realitas) selesai</td></tr><tr><td>20 tahun</td><td>Tahap kedua (pemberdayaan teknologi) sepenuhnya maju, hukum kultivasi dan rekayasa teknologi terintegrasi secara mendalam</td></tr><tr><td>40 tahun</td><td>Teknologi cermin salinan, teknologi ruang terisolasi mencapai produksi massal rekayasa, arkeologi antar-bidang memasuki era skala</td></tr><tr><td>60 tahun</td><td>Kultivator kelas peningkatan dimensi kesadaran pertama mencapai tingkat tinggi, tahap ketiga (evolusi kesadaran) dimulai</td></tr><tr><td>80 tahun</td><td>Pembangunan infrastruktur domain kesadaran selesai, teknologi migrasi kesadaran awalnya matang</td></tr><tr><td>100 tahun</td><td>Peningkatan dimensi bertahap pertama berhasil, peradaban simbiosis secara keseluruhan naik setengah tingkat dimensi</td></tr></tbody></table><h2 id="_9-era-republik-semua-ras-100-hingga-500-tahun" tabindex="-1">9. Era Republik Semua Ras (100 hingga 500 tahun) <a class="header-anchor" href="#_9-era-republik-semua-ras-100-hingga-500-tahun" aria-label="Permalink to &quot;9. Era Republik Semua Ras (100 hingga 500 tahun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>100 tahun</td><td>Republik semua ras secara resmi diumumkan terbentuk, semua ras cerdas mencapai persatuan setara dalam kerangka peradaban simbiosis</td></tr><tr><td>150 tahun</td><td>Penyusunan direktori semua ras selesai, mencakup semua ras cerdas yang diketahui</td></tr><tr><td>200 tahun</td><td>Perkawinan antar-ras dan peleburan budaya menjadi norma, ras campuran baru mulai muncul</td></tr><tr><td>300 tahun</td><td>Promosi bahasa umum semua ras selesai, hambatan komunikasi antar-ras pada dasarnya dihilangkan</td></tr><tr><td>400 tahun</td><td>Kebudayaan semua ras berkembang pesat, budaya tradisional setiap etnis dilindungi dan dikembangkan dalam kerangka simbiosis</td></tr><tr><td>500 tahun</td><td>Republik semua ras memasuki periode kedewasaan, syarat eksplorasi antar-bidang sepenuhnya matang</td></tr></tbody></table><h2 id="_10-era-eksplorasi-antar-bidang-500-hingga-2-000-tahun" tabindex="-1">10. Era Eksplorasi Antar-Bidang (500 hingga 2.000 tahun) <a class="header-anchor" href="#_10-era-eksplorasi-antar-bidang-500-hingga-2-000-tahun" aria-label="Permalink to &quot;10. Era Eksplorasi Antar-Bidang (500 hingga 2.000 tahun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>500 tahun</td><td>Rencana eksplorasi antar-bidang skala besar secara resmi dimulai, biro manajemen bidang terbentuk</td></tr><tr><td>600 tahun</td><td>Bidang yang telah dieksplorasi melebihi seribu, basis koordinat bidang umum awalnya terbentuk</td></tr><tr><td>800 tahun</td><td>Rencana arkeologi jarak jauh cermin salinan sepenuhnya matang, arkeologi antar-bidang memasuki zaman keemasan</td></tr><tr><td>1.000 tahun</td><td>Teknologi retrospeksi waktu mencapai terobosan, prinsip observasi dulu, kemudian intervensi terbatas secara resmi ditetapkan</td></tr><tr><td>1.200 tahun</td><td>Bidang yang telah dieksplorasi melebihi seratus ribu, hubungan diplomatik terjalin dengan puluhan peradaban bidang</td></tr><tr><td>1.500 tahun</td><td>Prinsip etika antar-bidang sepenuhnya diterapkan, interaksi antar-peradaban memasuki era standarisasi</td></tr><tr><td>1.800 tahun</td><td>Mekanisme pencegahan paradoks waktu sepenuhnya matang, arkeologi retrospeksi waktu mencapai skala</td></tr><tr><td>2.000 tahun</td><td>Eksplorasi antar-bidang mencapai hasil gemilang, syarat era simbiosis antarbintang sepenuhnya matang</td></tr></tbody></table><h2 id="_11-era-simbiosis-antarbintang-2-000-tahun-hingga-masa-depan" tabindex="-1">11. Era Simbiosis Antarbintang (2.000 tahun hingga masa depan) <a class="header-anchor" href="#_11-era-simbiosis-antarbintang-2-000-tahun-hingga-masa-depan" aria-label="Permalink to &quot;11. Era Simbiosis Antarbintang (2.000 tahun hingga masa depan)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Simpul Waktu</th><th>Peristiwa Penting</th></tr></thead><tbody><tr><td>2.000 tahun</td><td>Era simbiosis antarbintang secara resmi dimulai, tahap keempat (simbiosis antarbintang) sepenuhnya maju</td></tr><tr><td>2.500 tahun (prospek)</td><td>Jaringan jangkar kosmik awalnya terbentuk, mencakup semua bidang yang telah dieksplorasi</td></tr><tr><td>3.000 tahun (prospek)</td><td>Sistem simbiosis antar-bidang matang, semua ras mencapai simbiosis nyata dalam skala kosmik</td></tr><tr><td>5.000 tahun (prospek)</td><td>Peningkatan dimensi keseluruhan alam semesta selesai, Hengyuanzhou memasuki keadaan eksistensi dimensi yang lebih tinggi</td></tr><tr><td>Masa depan (prospek)</td><td>Peradaban Simbiosis Jangkar terus menjelajahi di luar alam semesta, menyebarkan konsep simbiosis ke eksistensi yang lebih luas</td></tr></tbody></table><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Tabel ringkas kronik adalah epik perjuangan Peradaban Simbiosis Jangkar, dari kebodohan ke kebangkitan, dari kelemahan ke kekuatan, dari bidang sendiri ke seluruh alam semesta. Setiap pergantian era adalah saksi kemenangan konsep simbiosis atas konsep penjarahan, kemajuan peradaban atas kemunduran barbar. Sejarah bukanlah debu masa lalu, melainkan benih masa depan—memahami sejarah ini berarti memahami dari mana peradaban simbiosis berasal dan ke mana ia pergi.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>70-Tabel Umum Pembagian Era</li><li>72-Era Kebangkitan Jangkar</li><li>79-Prospek Era Simbiosis Antarbintang</li></ul>',32)])])}const b=t(r,[["render",d]]);export{l as __pageData,b as default};
